use crate::config::parse_config;
use crate::models::Config;

/// Owns the active configuration.
pub struct Loader {
    config: Config,
}

impl Loader {
    pub fn new(config: Config) -> Self {
        Loader { config }
    }

    // Reload configuration from scratch.
    pub fn load(&mut self) {
        // Real cross-file call site of the free function parse_config():
        self.config = parse_config();
    }

    pub fn describe(&self) -> String {
        String::from("loader")
    }
}

// Entry point for the sample app.
use std::collections::HashMap;
use std::process;

mod cache;
mod config;
mod errors;
mod fs_utils;
mod handlers;
mod loader;
mod models;

use config::parse_config;
use loader::Loader;

fn main() {
    // Load configuration by calling parse_config() below.
    let cfg = parse_config();
    let mut loader = Loader::new(cfg);
    loader.load();

    // Route a couple of requests through the handlers.
    handlers::handle_get("/");
    handlers::handle_post("/submit");

    let mut seen: HashMap<String, i32> = HashMap::new();
    seen.insert("hits".to_string(), 1);

    save();

    // Old bootstrap path, kept for reference only:
    // parse_config();

    process::exit(0);
}

fn save() {
    // Persist state to disk.
    println!("saving");
}

